import React, { useState, useEffect } from 'react';
import axios from '../api/axios';

// Estados para o fluxo de senha
const PWD_STATE = {
    IDLE: 'IDLE', // Ocioso, apenas o botão "Alterar Senha" aparece
    REQUESTING_CODE: 'REQUESTING_CODE', // Enviando pedido de código
    CODE_SENT: 'CODE_SENT', // Código enviado, aguardando input do usuário
};

function MeuPerfilScreen({ onNavigateToHome }) {
    const [userData, setUserData] = useState({ telefone: '', endereco: '', cpf: '' });
    const [passwordData, setPasswordData] = useState({ nova_senha: '', codigo_verificacao: '' });
    const [passwordFlowState, setPasswordFlowState] = useState(PWD_STATE.IDLE);
    
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    useEffect(() => {
        const fetchUserData = async () => {
            // ... (lógica para buscar dados do usuário, igual a antes, mas agora buscando o CPF também)
            try {
                const token = localStorage.getItem('token');
                const response = await axios.get('/users/me', {
                    headers: { 'Authorization': `Bearer ${token}` }
                });
                setUserData({
                    telefone: response.data.telefone || '',
                    endereco: response.data.endereco || '',
                    cpf: response.data.cpf || ''
                });
            } catch (err) {
                setError('Não foi possível carregar seus dados.');
            } finally {
                setLoading(false);
            }
        };
        fetchUserData();
    }, []);

    const handleUserChange = (e) => {
        setUserData({ ...userData, [e.target.name]: e.target.value });
    };

    const handlePasswordChange = (e) => {
        setPasswordData({ ...passwordData, [e.target.name]: e.target.value });
    };

    const handleRequestCode = async () => {
        setPasswordFlowState(PWD_STATE.REQUESTING_CODE);
        setError(''); setSuccess('');
        try {
            const token = localStorage.getItem('token');
            await axios.post('/users/me/request-password-reset', {}, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            setSuccess('Código de verificação enviado para seu e-mail!');
            setPasswordFlowState(PWD_STATE.CODE_SENT);
        } catch (err) {
            setError(err.response?.data?.detail || 'Erro ao solicitar o código.');
            setPasswordFlowState(PWD_STATE.IDLE);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError(''); setSuccess('');
        setLoading(true);

        try {
            const token = localStorage.getItem('token');
            let payload = { ...userData };

            // Inclui dados de senha apenas se o usuário estiver nesse fluxo
            if (passwordFlowState === PWD_STATE.CODE_SENT && passwordData.nova_senha && passwordData.codigo_verificacao) {
                payload = { ...payload, ...passwordData };
            }

            const response = await axios.put('/users/me', payload, {
                headers: { 'Authorization': `Bearer ${token}` }
            });

            // Atualiza localStorage
            const localUserData = JSON.parse(localStorage.getItem('userData'));
            localUserData.telefone = response.data.telefone;
            // Adicione outros campos se necessário
            localStorage.setItem('userData', JSON.stringify(localUserData));

            setSuccess('Perfil atualizado com sucesso!');
            setPasswordData({ nova_senha: '', codigo_verificacao: '' });
            setPasswordFlowState(PWD_STATE.IDLE); // Reseta o fluxo de senha
        } catch (err) {
            setError(err.response?.data?.detail || 'Erro ao atualizar o perfil.');
        } finally {
            setLoading(false);
        }
    };

    const renderPasswordSection = () => {
        switch (passwordFlowState) {
            case PWD_STATE.IDLE:
                return <button type="button" className="btn-submit" style={{backgroundColor: '#6c757d'}} onClick={handleRequestCode}>Alterar Senha</button>;
            
            case PWD_STATE.REQUESTING_CODE:
                return <p>Enviando código...</p>;

            case PWD_STATE.CODE_SENT:
                return (
                    <>
                        <div className="form-group">
                            <label className="form-label">Código de Verificação (do seu e-mail)</label>
                            <input type="text" name="codigo_verificacao" className="form-input" value={passwordData.codigo_verificacao} onChange={handlePasswordChange} />
                        </div>
                        <div className="form-group">
                            <label className="form-label">Nova Senha</label>
                            <input type="password" name="nova_senha" className="form-input" value={passwordData.nova_senha} onChange={handlePasswordChange} />
                        </div>
                    </>
                );
            default: return null;
        }
    };

    if (loading && !userData.telefone) return <div className="loading-message">Carregando perfil...</div>;

    return (
        <div className="login-container">
            <div className="login-card" style={{maxWidth: '700px'}}>
                <div className="login-header">
                    <h1>Meu Perfil</h1>
                    <p>Atualize suas informações pessoais.</p>
                </div>
                {error && <div className="error-message">{error}</div>}
                {success && <div className="success-message">{success}</div>}
                <form onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label className="form-label">Telefone</label>
                        <input type="tel" name="telefone" className="form-input" value={userData.telefone} onChange={handleUserChange} />
                    </div>
                    <div className="form-group">
                        <label className="form-label">Endereço</label>
                        <input type="text" name="endereco" className="form-input" value={userData.endereco} onChange={handleUserChange} />
                    </div>
                    <div className="form-group">
                        <label className="form-label">CPF</label>
                        <input type="text" name="cpf" className="form-input" value={userData.cpf} onChange={handleUserChange} placeholder="000.000.000-00" />
                    </div>
                    
                    <hr style={{margin: '2rem 0'}} />
                    
                    {renderPasswordSection()}

                    <button type="submit" className="btn-submit" disabled={loading} style={{marginTop: '1.5rem'}}>
                        {loading ? 'Salvando...' : 'Salvar Alterações'}
                    </button>
                </form>
                <div className="login-footer">
                    <a href="#" onClick={(e) => { e.preventDefault(); onNavigateToHome(); }}>Voltar para o Início</a>
                </div>
            </div>
        </div>
    );
}

export default MeuPerfilScreen;
